"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["1848"],{35640(e){e.exports=JSON.parse('{"id":"FIN-952","slug":"seed-capital","term":"Seed Capital","also_known_as":[],"difficulty":"Intermediate","definition":"Seed capital is the initial money used to start a business, typically to develop a product, conduct market research and build a team before the company can attract larger investment.","explanation":["Seed capital is the earliest stage of formal start-up funding. It often comes from founders themselves, friends and family, angel investors, accelerators, crowdfunding or specialist seed-stage venture capital funds.","At the seed stage, companies usually have an idea, a small team and perhaps an early version of their product, but limited revenue. Seed funding helps them prove their concept and demonstrate enough progress to raise a larger round, typically a Series A.","For example, a start-up developing an app might raise seed funding of 1 million to hire engineers, build the product and gain its first users.","Seed investments are often structured as convertible notes or simple agreements for future equity, which convert into shares at a later funding round, avoiding the need to agree a precise valuation at such an early stage. Equity investments with an agreed valuation are also common.","Seed investing carries very high risk, since most early-stage companies fail. Investors accept this in the hope that a small number of successful investments will produce very large returns."],"note":"","total":1725,"prev":{"slug":"security-token","term":"Security Token"},"next":{"slug":"segment-margin","term":"Segment Margin"}}')}}]);